+  return {
+    notify(filePath: string) {
+      pending.add(filePath);
+      if (timer) clearTimeout(timer);
+      timer = setTimeout(flush, DEBOUNCE_MS);
+    },
+    cancel() {
+      if (timer) clearTimeout(timer);
+      pending.clear();
+    },
+  };
 }

